ALTER TABLE "dispatch_executions" ADD COLUMN "active_singleton_key" text;--> statement-breakpoint
ALTER TABLE "dispatch_executions" ADD COLUMN "active_singleton_name" text;--> statement-breakpoint
CREATE UNIQUE INDEX "dispatch_executions_active_singleton_unique" ON "dispatch_executions" USING btree ("tenant_id","active_singleton_name","active_singleton_key") WHERE "dispatch_executions"."active_singleton_key" IS NOT NULL AND "dispatch_executions"."state" NOT IN ('COMPLETED', 'CANCELLED', 'TIMED_OUT', 'FAILED', 'DEAD_LETTERED');--> statement-breakpoint
ALTER TABLE "dispatch_executions" ADD CONSTRAINT "dispatch_executions_active_singleton_pair" CHECK (("dispatch_executions"."active_singleton_name" IS NULL) = ("dispatch_executions"."active_singleton_key" IS NULL));